// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.File;
import java.io.IOException;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.TripleTerm;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.eclipse.rdf4j.sail.lmdb.model.LmdbIRI;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/** Verifies that one dataset materializer can overlap two native read callbacks. */
public class ValueStoreMaterializerConcurrentReadTest {

	private static final SimpleValueFactory FACTORY = SimpleValueFactory.getInstance();

	private ValueStore valueStore;

	@BeforeEach
	void setUp(@TempDir File dataDir) throws IOException {
		valueStore = new ValueStore(new File(dataDir, "values"), new LmdbStoreConfig()
				.setValueCacheSize(2)
				.setNamespaceCacheSize(2)
				.setValueIDCacheSize(2)
				.setValueEvictionInterval(-1));
	}

	@AfterEach
	void tearDown() throws IOException {
		if (valueStore != null) {
			valueStore.close();
		}
	}

	@Test
	void uncachedCallbacksMayOverlapOnSharedMaterializer() throws Exception {
		IRI firstExpected = FACTORY.createIRI("urn:materializer:overlap:", "first-" + "x".repeat(64));
		IRI secondExpected = FACTORY.createIRI("urn:materializer:overlap:", "second-" + "x".repeat(64));
		long firstId = store(firstExpected);
		long secondId = store(secondExpected);
		valueStore.clearCaches();

		CountDownLatch firstEntered = new CountDownLatch(1);
		CountDownLatch bothEntered = new CountDownLatch(2);
		CountDownLatch release = new CountDownLatch(1);
		ExecutorService executor = Executors.newFixedThreadPool(2);
		ValueStoreMaterializer materializer = null;
		try {
			materializer = new ValueStoreMaterializer(valueStore);
			LmdbIRI firstTemplate = (LmdbIRI) valueStore.getLazyValue(firstId, materializer);
			LmdbIRI secondTemplate = (LmdbIRI) valueStore.getLazyValue(secondId, materializer);
			ValueStoreRevision revision = firstTemplate.getValueStoreRevision();
			LmdbIRI first = new OverlapLmdbIRI(revision, firstId, true, firstEntered, bothEntered, release);
			LmdbIRI second = new OverlapLmdbIRI(revision, secondId, false, firstEntered, bothEntered, release);

			Future<String> firstRead = executor.submit(first::stringValue);
			assertTrue(firstEntered.await(5, TimeUnit.SECONDS), "first native callback must enter");
			Future<String> secondRead = executor.submit(second::stringValue);
			assertTrue(bothEntered.await(5, TimeUnit.SECONDS),
					"two callbacks sharing one retained transaction must overlap before either exits");

			release.countDown();
			assertEquals(firstExpected.stringValue(), firstRead.get(5, TimeUnit.SECONDS));
			assertEquals(secondExpected.stringValue(), secondRead.get(5, TimeUnit.SECONDS));
		} finally {
			release.countDown();
			if (materializer != null) {
				materializer.close();
			}
			executor.shutdownNow();
			assertTrue(executor.awaitTermination(5, TimeUnit.SECONDS), "overlap workers must terminate");
		}
	}

	@Test
	void concurrentNestedTripleMissesSurviveWriterCommitAndRetainedRenewal() throws Exception {
		TripleTerm firstExpected = triple("first");
		TripleTerm secondExpected = triple("second");
		long firstId = store(firstExpected);
		long secondId = store(secondExpected);
		valueStore.clearCaches();

		ExecutorService executor = Executors.newFixedThreadPool(2);
		try (ValueStoreMaterializer materializer = new ValueStoreMaterializer(valueStore)) {
			assertConcurrentTripleReads(executor, materializer, firstId, firstExpected, secondId, secondExpected);

			// A writer commit renews the tracked retained transaction. Clear dictionary caches so the second batch
			// reaches the same named triple-term DBI after renewal instead of succeeding from an earlier value object.
			store(FACTORY.createIRI("urn:materializer:commit:", "marker"));
			valueStore.clearCaches();

			assertConcurrentTripleReads(executor, materializer, firstId, firstExpected, secondId, secondExpected);
		} finally {
			executor.shutdownNow();
			assertTrue(executor.awaitTermination(5, TimeUnit.SECONDS), "triple readers must terminate");
		}
	}

	private void assertConcurrentTripleReads(ExecutorService executor, ValueStoreMaterializer materializer,
			long firstId, TripleTerm firstExpected, long secondId, TripleTerm secondExpected) throws Exception {
		CountDownLatch ready = new CountDownLatch(2);
		CountDownLatch start = new CountDownLatch(1);
		Future<TripleTerm> first = executor.submit(() -> readTriple(materializer, firstId, ready, start));
		Future<TripleTerm> second = executor.submit(() -> readTriple(materializer, secondId, ready, start));
		assertTrue(ready.await(5, TimeUnit.SECONDS), "all nested triple readers must be ready");
		start.countDown();
		assertTripleEquals(firstExpected, first.get(5, TimeUnit.SECONDS));
		assertTripleEquals(secondExpected, second.get(5, TimeUnit.SECONDS));
	}

	private TripleTerm readTriple(ValueStoreMaterializer materializer, long id, CountDownLatch ready,
			CountDownLatch start) throws Exception {
		ready.countDown();
		if (!start.await(5, TimeUnit.SECONDS)) {
			throw new IOException("Timed out waiting to start nested triple materialization");
		}
		return snapshotTriple((TripleTerm) valueStore.getLazyValue(id, materializer));
	}

	private static TripleTerm triple(String suffix) {
		String namespace = "urn:materializer:triple:" + suffix + ":";
		IRI subject = FACTORY.createIRI(namespace, "subject");
		IRI predicate = FACTORY.createIRI(namespace, "predicate");
		Literal object = FACTORY.createLiteral("object-" + suffix, FACTORY.createIRI(namespace, "datatype"));
		TripleTerm nested = FACTORY.createTripleTerm(
				FACTORY.createIRI(namespace, "nested-subject"),
				FACTORY.createIRI(namespace, "nested-predicate"), object);
		return FACTORY.createTripleTerm(subject, predicate, nested);
	}

	private static void assertTripleEquals(TripleTerm expected, TripleTerm actual) {
		assertEquals(expected.getSubject(), actual.getSubject());
		assertEquals(expected.getPredicate(), actual.getPredicate());
		Value expectedObject = expected.getObject();
		Value actualObject = actual.getObject();
		if (expectedObject instanceof TripleTerm expectedNested) {
			assertTrue(actualObject instanceof TripleTerm, "the nested object must remain a triple term");
			assertTripleEquals(expectedNested, (TripleTerm) actualObject);
		} else {
			assertEquals(expectedObject, actualObject);
		}
	}

	private static TripleTerm snapshotTriple(TripleTerm triple) {
		return FACTORY.createTripleTerm(
				FACTORY.createIRI(triple.getSubject().stringValue()),
				FACTORY.createIRI(triple.getPredicate().stringValue()),
				snapshotValue(triple.getObject()));
	}

	private static Value snapshotValue(Value value) {
		if (value instanceof TripleTerm triple) {
			return snapshotTriple(triple);
		}
		if (value instanceof IRI iri) {
			return FACTORY.createIRI(iri.stringValue());
		}
		Literal literal = (Literal) value;
		return literal.getLanguage()
				.map(language -> FACTORY.createLiteral(literal.getLabel(), language, literal.getBaseDirection()))
				.orElseGet(() -> FACTORY.createLiteral(literal.getLabel(),
						FACTORY.createIRI(literal.getDatatype().stringValue())));
	}

	private long store(Value value) throws IOException {
		valueStore.startTransaction(true);
		try {
			long id = valueStore.storeValue(value);
			valueStore.commit();
			return id;
		} catch (IOException | RuntimeException e) {
			valueStore.rollback();
			throw e;
		}
	}

	private static final class OverlapLmdbIRI extends LmdbIRI {

		private final boolean first;
		private final CountDownLatch firstEntered;
		private final CountDownLatch bothEntered;
		private final CountDownLatch release;

		private OverlapLmdbIRI(ValueStoreRevision revision, long internalID, boolean first,
				CountDownLatch firstEntered, CountDownLatch bothEntered, CountDownLatch release) {
			super(revision, internalID);
			this.first = first;
			this.firstEntered = firstEntered;
			this.bothEntered = bothEntered;
			this.release = release;
		}

		@Override
		public void setNamespaceAndIri(String namespace, String localName) {
			if (first) {
				firstEntered.countDown();
			}
			bothEntered.countDown();
			try {
				if (!release.await(5, TimeUnit.SECONDS)) {
					throw new IllegalStateException("Timed out waiting for overlapping materialization callbacks");
				}
			} catch (InterruptedException e) {
				Thread.currentThread().interrupt();
				throw new IllegalStateException("Interrupted while waiting for overlapping materialization callbacks",
						e);
			}
			super.setNamespaceAndIri(namespace, localName);
		}
	}
}
